import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../../providers/inventory_and_purchase_provider.dart';
import '../../providers/session_and_erp_provider.dart';
import '../../core/widgets/shared_widgets.dart';

class S14DisposalsScreen extends StatefulWidget{const S14DisposalsScreen({super.key});@override State<S14DisposalsScreen> createState()=>_S14DisposalsScreenState();}
class _S14DisposalsScreenState extends State<S14DisposalsScreen>{
 int? batchId;String reason='EXPIRED';final qty=TextEditingController();final method=TextEditingController(text:'إتلاف حسب تعليمات الجهة الصحية');final witness=TextEditingController();final authority=TextEditingController();
 @override void dispose(){qty.dispose();method.dispose();witness.dispose();authority.dispose();super.dispose();}
 @override Widget build(BuildContext context){final p=context.watch<InventoryAndPurchaseProvider>();final eligible=p.batches.where((b)=>b.totalUnits>0).toList();return Padding(padding:const EdgeInsets.all(12),child:Column(children:[const Text('محاضر الإعدام والإتلاف',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),DropdownButtonFormField<String>(value:reason,decoration:const InputDecoration(labelText:'سبب الإعدام'),items:const [DropdownMenuItem(value:'EXPIRED',child:Text('منتهي الصلاحية')),DropdownMenuItem(value:'BROKEN',child:Text('مكسور')),DropdownMenuItem(value:'DAMAGED_STORAGE',child:Text('تلف التخزين')),DropdownMenuItem(value:'RECALL',child:Text('سحب تشغيلة')),DropdownMenuItem(value:'CONTAMINATED',child:Text('تلوث'))],onChanged:(v)=>setState(()=>reason=v??reason)),DropdownButtonFormField<int>(value:batchId,decoration:const InputDecoration(labelText:'التشغيلة'),items:eligible.map((b)=>DropdownMenuItem(value:b.id,child:Text(b.drugName+' • '+b.batchNo+' • '+b.totalUnits.toString()+' حبة'))).toList(),onChanged:(v)=>setState(()=>batchId=v)),TextField(controller:qty,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'الكمية بالحبة')),TextField(controller:method,decoration:const InputDecoration(labelText:'طريقة الإتلاف')),TextField(controller:witness,decoration:const InputDecoration(labelText:'اسم الشاهد')),TextField(controller:authority,decoration:const InputDecoration(labelText:'رقم محضر الجهة الصحية')),const SizedBox(height:12),FilledButton.icon(onPressed:()=>_submit(p),icon:const Icon(Icons.delete_forever),label:const Text('اعتماد محضر الإعدام')),const Divider(),Expanded(child:ListView(children:p.disposals.map((d)=>ListTile(title:Text(d.disposalNo),subtitle:Text(d.reason+' • '+d.disposalDate+' • '+d.status),trailing:Text(d.totalCostValue.toStringAsFixed(2)))).toList()))]));}
 Future<void> _submit(InventoryAndPurchaseProvider p)async{final id=batchId;final amount=int.tryParse(qty.text)??0;if(id==null||amount<=0||witness.text.trim().isEmpty){_message('حدد التشغيلة والكمية واسم الشاهد');return;}final session=context.read<SessionAndErpProvider>();final approved=await ManagerPinDialog.show(context,verifier:session.verifyManagerPin);if(!approved)return;try{p.branchId=session.branchId;await p.createDisposal(reason:reason,method:method.text,witness:witness.text,authority:authority.text,items:[(batchId:id,qtyUnits:amount)]);qty.clear();_message('تم اعتماد محضر الإعدام وترحيل تكلفة الخسارة');}catch(e){_message(e.toString());}}
 void _message(String v)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(v)));
}
